 edge(){const inside=mk(ctr(0),ctr(-2),'stone',{placed:true,static:false}),outside=mk(ctr(-2),ctr(-4),'stone',{placed:true,static:false});inside.game.max=outside.game.max=20;moonfireImpactV81({x:0,y:-64,seed:8,vx:.1,size:4},inside);return {inside:inside.game.hits,outside:outside.game.hits}},
 victims(){const q=createMinerAt(16,-100,{level:1,gold:7}),a=wildlifeNewV71('wood-mouse',{x:35,y:-90});a.x=35;a.y=-90;wildlifeV71.push(a);becomeFeyV75(a);const wild=wildlifeNewV71('bird',{x:-25,y:-70});wild.x=-25;wild.y=-70;wildlifeV71.push(wild);moonfireImpactV81({x:16,y:-80,seed:9,vx:0,size:4},null);return {worker:miners.has(q),ghost:minerGhostsV42.has(q.game.id),fey:wildlifeV71.includes(a),wild:wildlifeV71.includes(wild),body:feyBodiesV75.has(a.id),blood:fairyBloodV75.length}},
