(async()=>{const browser=await chromium.launch({headless:true,executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome'}),p=await browser.newPage({viewport:{width:1280,height:900}}),errors=[];p.on('pageerror',e=>errors.push(e.message));p.on('console',m=>{if(m.type()==='error')errors.push(m.text())});await p.addInitScript(()=>requestAnimationFrame=()=>0);await p.route('**/game-v83-brimstone.txt*',async r=>{const a=await r.fetch();await r.fulfill({response:a,body:await a.text()+'\n'+hook})});await p.goto(base);await p.waitForFunction(()=>window.brimTest&&window.__buttonwood,null,{polling:100});await p.evaluate(()=>brimTest.fresh());const armor=await p.evaluate(()=>brimTest.armor());assert.deepEqual(armor,{hits:1,max:3,nail:false,static:false,pins:0});const one=await p.evaluate(()=>brimTest.armor(1));assert.equal(one.hits,0);assert(!one.nail&&!one.static);const mask=await p.evaluate(()=>brimTest.mask());assert.equal(mask.length,12);for(const y of [-2,-1,0,1])assert.equal(mask.filter(p=>p.cy===y).length,y===-2||y===1?2:4);await p.evaluate(()=>brimTest.fresh());const damage=await p.evaluate(()=>brimTest.damage());assert(damage.first.present&&!damage.first.nail&&!damage.first.static);assert.equal(damage.first.hits,0);assert(damage.first.speed>0);assert(damage.present&&damage.gold);assert.equal(damage.hits,1);await p.evaluate(()=>brimTest.fresh());const edge=await p.evaluate(()=>brimTest.edge());assert.equal(edge.inside,2);assert.equal(edge.outside,0);await p.evaluate(()=>brimTest.fresh());const fracture=await p.evaluate(()=>brimTest.fracture());assert.equal(fracture.first.count,25);assert.equal(fracture.first.damaged,12);assert.equal(fracture.first.untouched,13);assert(fracture.first.hits.every(h=>h===0||h===1));assert.equal(fracture.first.cost,25);assert(fracture.first.maxWidth<32);assert.equal(fracture.left,13,'second blast removes only worn stone cells');const strong=await p.evaluate(()=>brimTest.fracture('obsidian'));assert.equal(strong.left,25,'obsidian fragments survive repeated blasts');assert(strong.hits.every(h=>h<=1),'each cell struck once per explosion');const deep=await p.evaluate(()=>brimTest.fracture('deepslate',.27));assert.equal(deep.left,25);assert(deep.hits.every(h=>h<=2));await p.evaluate(()=>brimTest.fresh());await p.evaluate(s=>brimTest.restore(s),strong.save);const savedPieces=await p.evaluate(()=>brimTest.pieces());assert.equal(savedPieces.length,25);assert(savedPieces.every(q=>q.w<32&&q.h<32&&q.hits<=1));await p.evaluate(()=>brimTest.fresh());const victims=await p.evaluate(()=>brimTest.victims());assert(!victims.worker&&victims.ghost&&!victims.fey&&!victims.wild&&!victims.body);assert.equal(victims.blood,0);const collateral=await p.evaluate(()=>brimTest.collateral());assert(collateral.wear===2&&collateral.persisted===2&&!collateral.building&&collateral.fairy);assert.equal(await p.evaluate(()=>brimTest.directWild()),false,'direct swept hit kills an airborne wild animal');const scene=await p.evaluate(()=>brimTest.scene());assert(scene.spawned>=5);assert(scene.rocks<=24&&scene.burst<=18);assert(scene.loose>0);assert(scene.animals<7||scene.workers<3,'barrage is lethal in the actual demo');assert(await p.evaluate(()=>brimTest.allHits()));const qa=path.join(__dirname,'../buttonwood/qa/brimstone');fs.mkdirSync(qa,{recursive:true});await p.screenshot({path:path.join(qa,'barrage.png')});const save=await p.evaluate(()=>brimTest.save());assert(save.structuresV46.moonfireV81.brimstoneV83);await p.evaluate(s=>brimTest.restore(s),save);assert.equal(await p.evaluate(()=>brimTest.sky().spawned),save.structuresV46.moonfireV81.spawned);const before=await p.evaluate(()=>brimTest.sky().elapsed);await p.evaluate(()=>{brimTest.pause();brimTest.step(1000)});assert.equal(await p.evaluate(()=>brimTest.sky().elapsed),before);await p.evaluate(()=>skyStackPause.resume());await p.evaluate(()=>brimTest.render());assert.deepEqual(errors,[]);console.log('PASS nail armor/first point/general damage/unpinning, 0xx0 AoE shape/no corner damage, local cell wear/fracture/rotation/strong-material survival/save/impulses/no rewards, Worker/Fey/wild deaths/no taint, actual lethal barrage, budgets/save/pause');await browser.close()})().catch(e=>{console.error(e);process.exit(1)});
